extension ProjectWorkspaceView {
    var projectsLibrary: some View {
        ScrollView(.vertical, showsIndicators: false) {
            VStack(alignment: .leading, spacing: 22) {
                HStack(alignment: .top, spacing: 18) {
                    VStack(alignment: .leading, spacing: 8) {
                        Text("Projects")
                            .font(WalkableTypography.display(32))
                            .foregroundStyle(WalkableDesign.ink)
                        Text("Pick a project, or start new research.")
                            .font(WalkableTypography.ui(13, weight: .semibold))
                            .foregroundStyle(WalkableDesign.secondaryText)
                    }
                    Spacer()
                }

                HStack(spacing: 10) {
                    TextField("What do you want to learn or recreate?", text: $prompt)
                        .textFieldStyle(.plain)
                        .font(WalkableTypography.ui(14, weight: .medium))
                        .foregroundStyle(WalkableDesign.ink)
