                }

                if state.creativeProjects.isEmpty {
                    emptyProjectState
                } else {
                    LazyVGrid(
                        columns: [GridItem(.adaptive(minimum: 430, maximum: 620), spacing: 16, alignment: .top)],
                        alignment: .leading,
                        spacing: 16
                    ) {
                        ForEach(Array(state.creativeProjects.enumerated()), id: \.element.id) { index, project in
                            projectShelfCard(project, isPrimary: index == 0)
                        }
                    }
                }
            }
            .padding(WalkableSpacing.shell)
        }
    }

    func projectShelfCard(_ project: CreativeProject, isPrimary: Bool) -> some View {
        HStack(alignment: .top, spacing: 16) {
            Button {
                onResumeProject(project)
            } label: {
                projectCover(project, size: 136)
                .contentShape(RoundedRectangle(cornerRadius: WalkableCorners.card, style: .continuous))
            }
            .buttonStyle(.plain)

            VStack(alignment: .leading, spacing: 10) {
                Button {
                    onResumeProject(project)
                } label: {
                    VStack(alignment: .leading, spacing: 6) {
                        Text(project.title)
                            .font(WalkableTypography.ui(18, weight: .extrabold))
                            .foregroundStyle(WalkableDesign.ink)
                            .lineLimit(2)
                        Text(projectSubtitle(project))
                            .font(WalkableTypography.ui(12, weight: .semibold))
                            .foregroundStyle(WalkableDesign.secondaryText)
                            .lineLimit(2)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                }
                .buttonStyle(.plain)

                VStack(alignment: .leading, spacing: 4) {
                    Text(project.latestRun.map(themedRunTitle) ?? "No research yet")
                        .font(WalkableTypography.ui(11, weight: .extrabold))
                        .foregroundStyle(WalkableDesign.ink)
                        .lineLimit(1)
                    Text("\(project.wikiPages.count) notes · \(project.modules.count) lessons · \(project.sourceAudioPath == nil ? "source optional" : "source linked")")
                        .font(WalkableTypography.mono(9, weight: .bold))
                        .foregroundStyle(WalkableDesign.secondaryText)
                        .lineLimit(1)
                }

                Spacer()

                HStack(spacing: 10) {
                    Button("Open project") { onResumeProject(project) }
                        .buttonStyle(.plain)
                        .font(WalkableTypography.ui(11, weight: .extrabold))
                        .foregroundStyle(WalkableDesign.ember)

                    Spacer()

                    Button(isPrimary ? "Continue research" : "Resume") { onResumeProject(project) }
                        .buttonStyle(.plain)
                        .font(WalkableTypography.ui(11, weight: .extrabold))
                        .foregroundStyle(WalkableDesign.onAccent)
                        .padding(.horizontal, 12)
                        .padding(.vertical, 8)
                        .background(RoundedRectangle(cornerRadius: WalkableCorners.inner, style: .continuous).fill(WalkableDesign.ember))
                }
            }
            .frame(maxWidth: .infinity, minHeight: 136, alignment: .topLeading)
        }
        .padding(WalkableSpacing.generous)
        .background(
            RoundedRectangle(cornerRadius: WalkableCorners.card, style: .continuous)
                .fill(isPrimary ? WalkableDesign.blush.opacity(0.22) : WalkableDesign.surface.opacity(0.80))
        )
        .overlay(
            RoundedRectangle(cornerRadius: WalkableCorners.card, style: .continuous)
                .stroke(WalkableDesign.line.opacity(isPrimary ? 0.20 : 0.12), lineWidth: 1)
        )
        .shadow(color: WalkableDesign.blush.opacity(isPrimary ? 0.16 : 0.06), radius: isPrimary ? 18 : 10, x: 0, y: isPrimary ? 8 : 4)
    }

    @ViewBuilder
    func projectCover(_ project: CreativeProject, size: CGFloat) -> some View {
        let shape = RoundedRectangle(cornerRadius: 12, style: .continuous)
        if let image = projectCoverImage(project) {
            Image(nsImage: image)
                .resizable()
                .scaledToFill()
                .frame(width: size, height: size)
                .clipShape(shape)
                .overlay(shape.stroke(WalkableDesign.line.opacity(0.12), lineWidth: 1))
                .shadow(color: WalkableDesign.violet.opacity(0.12), radius: 10, x: 0, y: 5)
        } else {
            DefaultProjectCoverView()
            .frame(width: size, height: size)
            .clipShape(shape)
            .overlay(shape.stroke(WalkableDesign.line.opacity(0.10), lineWidth: 1))
        }
    }

    func projectCoverImage(_ project: CreativeProject) -> NSImage? {
        guard let coverImagePath = project.coverImagePath, !coverImagePath.isEmpty else { return nil }
        let url: URL
        if coverImagePath.hasPrefix("/") {
            url = URL(fileURLWithPath: coverImagePath)
        } else {
            url = CreativeProjectStore.projectDirectory(for: project.id).appendingPathComponent(coverImagePath)
        }
        return NSImage(contentsOf: url)
    }

    func researchSessionButton(_ run: ProjectRun, isSelected: Bool) -> some View {
        Button {
            selectedRunID = run.id
        } label: {
            VStack(alignment: .leading, spacing: 7) {
                HStack(spacing: 8) {
                    Circle()
                        .fill(color(for: run.status))
                        .frame(width: 8, height: 8)
                    Text(run.title)
                        .font(WalkableTypography.ui(12, weight: .extrabold))
                        .foregroundStyle(WalkableDesign.ink)
                        .lineLimit(1)
                    Spacer()
                }

                Text(run.goal)
                    .font(WalkableTypography.ui(10, weight: .semibold))
                    .foregroundStyle(WalkableDesign.secondaryText)
                    .lineLimit(2)

                HStack(spacing: 6) {
                    Text(displayStatus(run.status))
                        .font(WalkableTypography.mono(8, weight: .extrabold))
                        .foregroundStyle(color(for: run.status))
                    Spacer()
                    Text(run.startedAt, style: .time)
                        .font(WalkableTypography.mono(8, weight: .bold))
                        .foregroundStyle(WalkableDesign.faintText)
                }
            }
            .padding(11)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(isSelected ? WalkableDesign.blush.opacity(0.34) : WalkableDesign.surface.opacity(0.72))
            .overlay(RoundedRectangle(cornerRadius: WalkableCorners.inner, style: .continuous).stroke(isSelected ? WalkableDesign.line : WalkableDesign.line.opacity(0.22), lineWidth: 1))
        }
        .buttonStyle(.plain)
    }

    func selectedResearchRun(_ project: CreativeProject) -> ProjectRun? {
        let runs = project.runs.sorted { $0.startedAt > $1.startedAt }
        if let selectedRunID, let selected = runs.first(where: { $0.id == selectedRunID }) {
            return selected
        }
        return runs.first
    }

    func color(for status: ProjectRunStatus) -> Color {
        switch status {
        case .queued: return WalkableDesign.violet
        case .running: return WalkableDesign.ember
        case .completed: return WalkableDesign.moss
        case .failed: return WalkableDesign.blush
        }
    }

    func color(for kind: ProjectEventKind) -> Color {
        switch kind {
        case .thought: return WalkableDesign.violet
        case .tool: return WalkableDesign.ember
        case .artifact: return WalkableDesign.gold
        case .wiki: return WalkableDesign.moss
        case .module: return WalkableDesign.blush
        case .warning: return WalkableDesign.gold
        case .error: return WalkableDesign.ember
        }
    }

    func compactProjectEvent(_ event: ProjectEvent) -> some View {
        HStack(alignment: .top, spacing: 10) {
            Circle()
                .fill(color(for: event.kind))
                .frame(width: 8, height: 8)
                .padding(.top, 5)
            VStack(alignment: .leading, spacing: 3) {
                Text(event.title)
                    .font(WalkableTypography.ui(12, weight: .extrabold))
                    .foregroundStyle(WalkableDesign.ink)
                Text(event.detail)
                    .font(WalkableTypography.ui(11, weight: .medium))
                    .foregroundStyle(WalkableDesign.secondaryText)
                    .lineLimit(2)
            }
            Spacer()
        }
        .padding(10)
        .background(RoundedRectangle(cornerRadius: WalkableCorners.inner, style: .continuous).fill(WalkableDesign.surface.opacity(0.74)))
        .overlay(RoundedRectangle(cornerRadius: WalkableCorners.inner, style: .continuous).stroke(WalkableDesign.line.opacity(0.22), lineWidth: 1))
    }

    func agentRunPanel(_ project: CreativeProject, run: ProjectRun?) -> some View {
        @Bindable var bindableState = state
        let isLive = state.isThinking || run?.status == .running
        let chatState = state.liveCodexChatState(for: run)
        let messages = chatState.map { WalkableCodexProjection.visibleMessages($0.messages) } ?? []
        let lifecycleEvents = WalkableCodexProjection.visibleLifecycleEvents(chatState?.lifecycleEvents ?? [])
        let activeTurn = chatState.flatMap { WalkableCodexProjection.activeTurnState(from: $0, isThinking: state.isThinking) }


