private struct ProjectIndexRow: View {
    let project: ClayProject

    var body: some View {
        ClayCard(radius: 18, padding: 18) {
            HStack(alignment: .center, spacing: 18) {
                ClayIcon(symbol: "folder.fill", color: accentColor, size: 58, glyphScale: 0.48)

                VStack(alignment: .leading, spacing: 8) {
                    Text(project.title)
                        .font(ClayFont.title(21))
                        .foregroundStyle(Clay.ink)
                        .clayInkShadow(0.44)
                        .lineLimit(1)
                        .minimumScaleFactor(0.76)

                    Text(project.goal)
                        .font(ClayFont.medium(13))
                        .foregroundStyle(Clay.inkSoft)
                        .lineLimit(1)
                        .minimumScaleFactor(0.75)
                        .clayInkShadow(0.26)

                    HStack(spacing: 18) {
                        ProjectIndexMeta(symbol: "book.closed.fill", color: Clay.mint, text: researchText)
                        ProjectIndexMeta(symbol: "graduationcap.fill", color: Clay.gold, text: lessonText)
                        ProjectIndexMeta(symbol: "target", color: Clay.rose, text: currentMissionText)
                    }
                }

                Spacer(minLength: 14)

                VStack(alignment: .trailing, spacing: 10) {
                    Text(project.status.label)
                        .font(ClayFont.bold(12))
                        .foregroundStyle(accentColor)
                        .clayInkShadow(0.26)
                        .lineLimit(1)

                    ProjectIndexProgress(progress: project.lessonProgress)
                        .frame(width: 116, height: 10)

                    HStack(spacing: 7) {
                        Text("Open")
                            .font(ClayFont.semibold(12))
                            .foregroundStyle(Clay.inkSoft)
                            .clayInkShadow(0.24)
                        ClaySymbol(symbol: "arrow.right", color: accentColor, size: 13)
                    }
                }
                .frame(width: 138, alignment: .trailing)
            }
        }
        .clayHoverLift(radius: 18)
    }

    private var accentColor: Color {
        switch project.status {
        case .idle: Clay.violetLit
        case .researching: Clay.gold
        case .waitingForInput: Clay.rose
        case .ready: Clay.mint
        case .failed: Clay.deepRose
        }
    }

    private var researchText: String {
        if project.researchRun.hasStartedCodex { return "Notebook started" }
        if !project.lessonCandidates.isEmpty { return "Notebook synthesized" }
        return "Research queued"
    }

    private var lessonText: String {
        if project.hasFormedLessons {
            return count(project.lessons.count, singular: "lesson") + " formed"
        }
        if !project.lessonCandidates.isEmpty {
            return count(project.lessonCandidates.count, singular: "candidate")
        }
        return "No lessons yet"
    }

    private var currentMissionText: String {
        project.currentLesson?.title ?? "No current mission"
    }

    private func count(_ value: Int, singular: String) -> String {
        value == 1 ? "1 \(singular)" : "\(value) \(singular)s"
    }
}

